import Foundation

/// Menswear know-how the engine applies to every outfit: which colors work together, which textures clash,
/// which fabrics belong to which seasons and what never belongs in a style. Loaded from `knowledge.json`
/// (generated by `tools/knowledge/style_library.py`).
public struct StyleKnowledge: Sendable {
    /// 2 classic, 1 good, 0 neutral, -1 avoid. Key: the two color names sorted and joined by "|".
    let pairScores: [String: Int]
    let texturedKeywords: [String]
    let heavyTextureKeywords: [String]
    let seasonalKeywords: [(seasons: Set<Season>, keywords: [String])]
    let formalityKeywords: [(keyword: String, formality: Int)]
    let exclusions: [Style: (categories: Set<GarmentCategory>, keywords: [String])]
    /// Short styling rules, in plain words, for the app to show.
    public let principles: [String]
    let fits: [(fit: String, keywords: [String])]
    let categoryFits: [String: String]
    let volumeKeywords: [String]

    public static let shared: StyleKnowledge = {
        guard let url = Bundle.module.url(forResource: "knowledge", withExtension: "json"),
              let data = try? Data(contentsOf: url),
              let file = try? JSONDecoder().decode(KnowledgeFile.self, from: data)
        else { return StyleKnowledge(file: KnowledgeFile()) }
        return StyleKnowledge(file: file)
    }()

    init(file: KnowledgeFile) {
        var scores: [String: Int] = [:]
        for pair in file.colorPairs { scores[Self.key(pair.a, pair.b)] = pair.score }
        pairScores = scores
        texturedKeywords = file.textures["textured"] ?? []
        heavyTextureKeywords = file.heavyTextures
        seasonalKeywords = file.seasonalMaterials.map { entry in
            (seasons: Set(entry.seasons.compactMap(Season.init(rawValue:))), keywords: entry.keywords)
        }
        formalityKeywords = file.formalityKeywords.map { (keyword: $0.keyword, formality: $0.formality) }
        var styleExclusions: [Style: (categories: Set<GarmentCategory>, keywords: [String])] = [:]
        for entry in file.styleExclusions {
            guard let style = Style(rawValue: entry.style) else { continue }
            styleExclusions[style] = (categories: Set(entry.categories.compactMap(GarmentCategory.init(rawValue:))), keywords: entry.keywords)
        }
        exclusions = styleExclusions
        principles = file.principles
        fits = file.fits.map { (fit: $0.fit, keywords: $0.keywords) }
        categoryFits = file.categoryFits
        volumeKeywords = file.volumeKeywords
    }

    private static func key(_ a: String, _ b: String) -> String { a < b ? "\(a)|\(b)" : "\(b)|\(a)" }

    // MARK: Colors

    /// How well two colors sit together in one outfit (2 classic ... -1 avoid).
    public func colorScore(_ a: String, _ b: String) -> Int {
        if a == b { return a == "denim" ? -1 : 0 } // double denim in one wash looks like a uniform
        return pairScores[Self.key(a, b)] ?? 0
    }

    /// Colors of the clothes themselves; shoes and accessories follow their own rules (black shoes with navy is classic).
    private func clothingColors(_ garments: [EngineGarment]) -> [String] {
        garments.filter { $0.slot != .accessory && $0.slot != .shoes }.map(\.primaryColor)
    }

    /// Average pair score of the outfit's clothing colors (-1 ... 2); 0 for fewer than two pieces.
    public func colorHarmony(_ garments: [EngineGarment]) -> Double {
        let colors = clothingColors(garments)
        guard colors.count > 1 else { return 0 }
        var total = 0, pairs = 0
        for i in colors.indices {
            for j in colors.indices where j > i {
                total += colorScore(colors[i], colors[j])
                pairs += 1
            }
        }
        return Double(total) / Double(pairs)
    }

    /// True if two of the outfit's clothes are in colors that should not be worn together.
    public func hasColorClash(_ garments: [EngineGarment]) -> Bool {
        let colors = clothingColors(garments)
        for i in colors.indices {
            for j in colors.indices where j > i && colorScore(colors[i], colors[j]) < 0 { return true }
        }
        return false
    }

    // MARK: Textures and cuts

    /// Suit jackets and suit trousers belong together, never as separates.
    public func isSuitPiece(_ garment: EngineGarment) -> Bool {
        let text = garment.searchText
        guard text.contains("suit") else { return false }
        return !["tracksuit", "track suit", "jumpsuit", "swimsuit", "sweatsuit"].contains { text.contains($0) }
    }

    public func isHeavyTexture(_ garment: EngineGarment) -> Bool {
        let text = garment.searchText
        return heavyTextureKeywords.contains { text.contains($0) }
    }

    public func isTextured(_ garment: EngineGarment) -> Bool {
        let text = garment.searchText
        return texturedKeywords.contains { text.contains($0) }
    }

    /// Two heavy textures on top and bottom (a cable knit with corduroys) look clumsy.
    public func hasTextureClash(_ candidate: OutfitCandidate) -> Bool {
        guard let top = candidate.pieces[.top], let bottom = candidate.pieces[.bottom] else { return false }
        return isHeavyTexture(top) && isHeavyTexture(bottom)
    }

    /// One textured piece against smooth ones reads as deliberate.
    public func hasTextureContrast(_ garments: [EngineGarment]) -> Bool {
        let core = garments.filter { $0.slot != nil && $0.slot != .accessory && $0.slot != .shoes }
        let textured = core.filter(isTextured).count
        return textured >= 1 && textured < core.count
    }

    // MARK: Silhouette

    /// The shape of a bottom: "wide" (high-waisted, pleated), "relaxed", "slim", "tailored" or "straight".
    public func fit(of garment: EngineGarment) -> String {
        let text = " " + garment.searchText
        return fits.first { entry in entry.keywords.contains { text.contains($0) } }?.fit
            ?? categoryFits[garment.category.rawValue] ?? "straight"
    }

    /// Chunky knits, hoodies and the like change the upper-body shape.
    public func hasVolume(_ garment: EngineGarment) -> Bool {
        let text = garment.searchText
        return garment.category == .hoodie || volumeKeywords.contains { text.contains($0) }
    }

    /// The outfit's shape, e.g. "wide", "slim+volume".
    public func silhouette(of candidate: OutfitCandidate) -> String {
        let legs = candidate.pieces[.bottom].map(fit(of:)) ?? "none"
        let volume = candidate.pieces[.top].map(hasVolume) ?? false
        return volume ? legs + "+volume" : legs
    }

    // MARK: Seasons, formality, styles

    /// Seasons a fabric belongs to (linen: spring and summer), or nil when the fabric says nothing.
    public func inferredSeasons(for garment: EngineGarment) -> Set<Season>? {
        let text = garment.searchText
        guard !text.trimmingCharacters(in: .whitespaces).isEmpty else { return nil }
        return seasonalKeywords.first { entry in entry.keywords.contains { text.contains($0) } }?.seasons
    }

    /// The typical formality of this type of garment ("joggers" 1, "derby shoes" 4), if the type is known.
    public func typicalFormality(for garment: EngineGarment) -> Int? {
        let text = garment.searchText
        return formalityKeywords.first { text.contains($0.keyword) }?.formality
    }

    /// The garment's formality, corrected when its type clearly says otherwise (joggers marked smart).
    public func effectiveFormality(for garment: EngineGarment) -> Int {
        guard let typical = typicalFormality(for: garment), abs(typical - garment.formality) >= 2 else { return garment.formality }
        return typical
    }

    /// Whether the garment never belongs in this style (sneakers with a suit, joggers in smart casual).
    public func isExcluded(_ garment: EngineGarment, from style: Style) -> Bool {
        guard let rule = exclusions[style] else { return false }
        if rule.categories.contains(garment.category) { return true }
        let text = garment.searchText
        return rule.keywords.contains { text.contains($0) }
    }

    /// Excluded from every one of the styles (a recipe written for several styles may use it in any of them).
    public func isExcluded(_ garment: EngineGarment, fromAll styles: [Style]) -> Bool {
        !styles.isEmpty && styles.allSatisfy { isExcluded(garment, from: $0) }
    }
}

extension EngineGarment {
    /// Material and type, lowercased, for keyword rules (" suit" with a leading space matches "wool suit").
    var searchText: String { (material + " " + subcategory).lowercased() }
}

// MARK: File format

struct KnowledgeFile: Decodable {
    struct ColorPair: Decodable { var a: String; var b: String; var score: Int }
    struct SeasonalMaterial: Decodable { var seasons: [String]; var keywords: [String] }
    struct FormalityKeyword: Decodable { var keyword: String; var formality: Int }
    struct StyleExclusion: Decodable { var style: String; var categories: [String]; var keywords: [String] }
    struct Fit: Decodable { var fit: String; var keywords: [String] }

    var colorPairs: [ColorPair] = []
    var textures: [String: [String]] = [:]
    var heavyTextures: [String] = []
    var seasonalMaterials: [SeasonalMaterial] = []
    var formalityKeywords: [FormalityKeyword] = []
    var styleExclusions: [StyleExclusion] = []
    var principles: [String] = []
    var fits: [Fit] = []
    var categoryFits: [String: String] = [:]
    var volumeKeywords: [String] = []
}
